import numpy as np
def cell(a,b,c,al,be,ga):
    al,be,ga=np.radians([al,be,ga])
    cv=[c*np.cos(be), c*(np.cos(al)-np.cos(be)*np.cos(ga))/np.sin(ga)]
    cz=np.sqrt(c*c-cv[0]**2-cv[1]**2)
    return np.array([[a,0,0],[b*np.cos(ga),b*np.sin(ga),0],[cv[0],cv[1],cz]])
def dists(L,sites,sp='S'):
    fr=np.array([s[1:] for s in sites if s[0]==sp]); M=cell(*L)
    out=[]
    for i,f in enumerate(fr):
        best=[]
        for j,g in enumerate(fr):
            for n in np.array(np.meshgrid([-1,0,1],[-1,0,1],[-1,0,1])).reshape(3,-1).T:
                if i==j and not n.any(): continue
                d=np.linalg.norm((g+n-f)@M); best.append(d)
        out.append(min(best))
    return np.round(sorted(out)[:6],3)
